-- Localization for tips table
ALTER TABLE tips
ADD COLUMN title_en VARCHAR(255),
ADD COLUMN title_es VARCHAR(255),
ADD COLUMN text_en TEXT,
ADD COLUMN text_es TEXT;

UPDATE tips SET title_en = title, title_es = title, text_en = text, text_es = text;

-- Delete old columns after migration
ALTER TABLE tips
DROP COLUMN title,
DROP COLUMN text;

-- Traducciones al español de los consejos (IDs 1–110).
UPDATE tips SET title_es = 'La naturaleza restaura el enfoque', text_es = 'Pasar tiempo en entornos naturales ayuda a recuperar la atención dirigida después del cansancio mental.\n\nIncluso un paseo corto entre los árboles puede mejorar la concentración y el rendimiento cognitivo.' WHERE id = 1;
UPDATE tips SET title_es = 'Al cerebro le gustan las señales claras', text_es = 'Los hábitos son más fáciles de adquirir cuando se vinculan a señales concretas.\n\nUna señal clara, como una hora, un lugar o un acontecimiento, ayuda al cerebro a saber exactamente cuándo actuar.' WHERE id = 2;
UPDATE tips SET title_es = 'Los planes «si... entonces...» funcionan', text_es = 'Es más probable que las personas cumplan sus objetivos cuando elaboran planes concretos.\n\nDecidir qué harás en una situación específica reduce las dudas y la necesidad de decidir sobre la marcha.' WHERE id = 3;
UPDATE tips SET title_es = 'La concentración es un recurso limitado', text_es = 'Concentrarse requiere esfuerzo mental y la capacidad de hacerlo puede agotarse con el tiempo.\n\nLos periodos de descanso ayudan a mantener el rendimiento y a prevenir el agotamiento mental.' WHERE id = 4;
UPDATE tips SET title_es = 'El estado de fluidez surge entre el aburrimiento y la ansiedad', text_es = 'Es más probable entrar en estado de fluidez cuando el reto está a la altura de tus habilidades.\n\nLas tareas demasiado fáciles aburren, mientras que las demasiado difíciles generan estrés.' WHERE id = 5;
UPDATE tips SET title_es = 'Las notificaciones tienen un coste oculto', text_es = 'Las interrupciones no solo rompen la concentración en el momento.\n\nEl cerebro suele seguir pensando en la distracción, lo que reduce el rendimiento incluso después de que haya terminado.' WHERE id = 6;
UPDATE tips SET title_es = 'La especificidad supera a la motivación', text_es = 'La motivación puede variar de un día a otro.\n\nLos planes claros sobre cuándo y dónde actuar suelen ser más fiables que esperar a sentir motivación.' WHERE id = 7;
UPDATE tips SET title_es = 'La fluidez altera la percepción del tiempo', text_es = 'Durante una concentración profunda, es frecuente perder la noción del tiempo.\n\nLas horas pueden parecer minutos cuando la atención está completamente absorbida por una tarea significativa.' WHERE id = 8;
UPDATE tips SET title_es = 'Los pequeños comienzos vencen a las grandes promesas', text_es = 'Empezar con una acción pequeña reduce la resistencia y facilita la constancia.\n\nCon el tiempo, los comienzos modestos pueden convertirse en hábitos más grandes.' WHERE id = 9;
UPDATE tips SET title_es = 'El entorno moldea la conducta', text_es = 'Lo que te rodea influye en tus acciones más de lo que muchas personas imaginan.\n\nDiseñar el entorno puede facilitar los buenos hábitos y dificultar los malos.' WHERE id = 10;
UPDATE tips SET title_es = 'La atención se puede entrenar', text_es = 'La concentración es una habilidad que mejora con la práctica.\n\nLas actividades que exigen atención sostenida pueden fortalecer la capacidad de resistir las distracciones.' WHERE id = 11;
UPDATE tips SET title_es = 'La reflexión necesita espacio mental', text_es = 'La estimulación constante deja poco espacio para reflexionar.\n\nLos momentos de calma permiten al cerebro procesar experiencias y obtener perspectivas más profundas.' WHERE id = 12;
UPDATE tips SET title_es = 'Los objetivos necesitan retroalimentación', text_es = 'Los objetivos claros y la retroalimentación inmediata son ingredientes fundamentales del estado de fluidez.\n\nSaber cómo vas ayuda a mantener el compromiso y la motivación.' WHERE id = 13;
UPDATE tips SET title_es = 'Los hábitos reducen la fatiga de decisión', text_es = 'Cada decisión consume energía mental.\n\nConvertir conductas útiles en hábitos libera recursos cognitivos para asuntos más importantes.' WHERE id = 14;
UPDATE tips SET title_es = 'La concentración prefiere una tarea a la vez', text_es = 'Centrarse en una sola tarea suele ser más eficiente que alternar entre varias.\n\nCambiar de tarea conlleva costes mentales que pasan desapercibidos.' WHERE id = 15;
UPDATE tips SET title_es = 'Tu cerebro busca señales', text_es = 'Cuando defines una señal que activa un hábito, tu atención se vuelve más sensible a ella.\n\nEl cerebro empieza a detectar de forma natural oportunidades para actuar.' WHERE id = 16;
UPDATE tips SET title_es = 'El trabajo profundo parece no requerir esfuerzo', text_es = 'Los estados de concentración intensa suelen sentirse sorprendentemente fluidos, aunque exijan mucha habilidad.\n\nEl esfuerzo se nota menos cuando la atención está completamente implicada.' WHERE id = 17;
UPDATE tips SET title_es = 'La motivación suele venir después de actuar', text_es = 'Muchas personas esperan a tener motivación para empezar. En realidad, actuar suele ser lo que genera la motivación para continuar.' WHERE id = 18;
UPDATE tips SET title_es = 'Caminar puede mejorar el pensamiento', text_es = 'Caminar aumenta el flujo sanguíneo y puede favorecer el pensamiento creativo.\n\nA muchas personas se les ocurren ideas con más facilidad mientras se mueven.' WHERE id = 19;
UPDATE tips SET title_es = 'El aburrimiento puede ser útil', text_es = 'Los momentos sin estímulos favorecen la reflexión y la imaginación.\n\nAlgunas de nuestras mejores ideas surgen cuando nada reclama nuestra atención.' WHERE id = 20;
UPDATE tips SET title_es = 'Los hábitos prosperan con la constancia', text_es = 'Los hábitos se fortalecen cuando se repiten en el mismo contexto.\n\nLa constancia enseña al cerebro a asociar una situación con una conducta concreta hasta que se vuelve automática.' WHERE id = 21;
UPDATE tips SET title_es = 'La concentración es más fácil cuando hay un propósito', text_es = 'Los objetivos significativos atraen la atención de forma natural.\n\nCuando comprendes por qué importa una tarea, es más fácil mantenerte implicado y resistir las distracciones.' WHERE id = 22;
UPDATE tips SET title_es = 'La fascinación suave restaura la atención', text_es = 'Estímulos tranquilos, como las nubes, el agua corriente o el susurro de las hojas, captan la mente sin exigir esfuerzo.\n\nEsto permite que la atención se recupere del cansancio.' WHERE id = 23;
UPDATE tips SET title_es = 'La multitarea suele ser un cambio constante de tarea', text_es = 'Lo que llamamos multitarea suele ser un cambio rápido de una tarea a otra.\n\nCada cambio tiene un pequeño coste cognitivo que puede reducir la eficiencia y aumentar los errores.' WHERE id = 24;
UPDATE tips SET title_es = 'Los hábitos sólidos necesitan señales claras', text_es = 'Cuanto más clara y visible sea una señal, más probable será que se produzca el hábito.\n\nLas señales eficaces eliminan la incertidumbre sobre cuándo actuar.' WHERE id = 25;
UPDATE tips SET title_es = 'La fluidez es gratificante por sí misma', text_es = 'Las actividades que producen fluidez suelen ser agradables incluso sin recompensas externas.\n\nLas personas las practican porque la experiencia en sí resulta satisfactoria y significativa.' WHERE id = 26;
UPDATE tips SET title_es = 'La recuperación mental mejora el rendimiento', text_es = 'Las personas productivas no se concentran sin parar.\n\nLos descansos estratégicos ayudan a mantener la concentración, la creatividad y la calidad de las decisiones.' WHERE id = 27;
UPDATE tips SET title_es = 'Los pequeños logros generan impulso', text_es = 'Los pequeños logros crean una sensación de progreso.\n\nEsa sensación suele aumentar la motivación y facilita las acciones futuras.' WHERE id = 28;
UPDATE tips SET title_es = 'La atención sigue al interés', text_es = 'El cerebro dedica de forma natural más recursos a lo que considera significativo, novedoso o gratificante.\n\nEl interés es uno de los motores más potentes de la concentración.' WHERE id = 29;
UPDATE tips SET title_es = 'La claridad vence a la complejidad', text_es = 'Los planes sencillos son más fáciles de recordar y llevar a cabo.\n\nCuanto más complicado es un sistema, más posibilidades hay de abandonarlo.' WHERE id = 30;
UPDATE tips SET title_es = 'El efecto Zeigarnik', text_es = 'Las tareas sin terminar tienden a permanecer activas en la mente. Por eso los objetivos pendientes vuelven una y otra vez a tus pensamientos hasta que los completas.' WHERE id = 31;
UPDATE tips SET title_es = 'Empezar es lo más difícil', text_es = 'A menudo, comenzar una tarea requiere más esfuerzo que continuarla.\n\nUna vez que se genera impulso, el cerebro ofrece menos resistencia a la actividad.' WHERE id = 32;
UPDATE tips SET title_es = 'El autocontrol depende del contexto', text_es = 'Las personas con buen autocontrol suelen evitar las tentaciones en vez de resistirse a ellas constantemente.\n\nUn entorno bien diseñado reduce la necesidad de fuerza de voluntad.' WHERE id = 33;
UPDATE tips SET title_es = 'Tu yo futuro puede parecerte un desconocido', text_es = 'De forma natural, valoramos más las recompensas inmediatas que los beneficios futuros.\n\nFortalecer el vínculo con tu yo futuro puede mejorar la toma de decisiones a largo plazo.' WHERE id = 34;
UPDATE tips SET title_es = 'La atención es selectiva', text_es = 'El cerebro filtra enormes cantidades de información cada segundo. Lo que percibes depende en gran medida de tus objetivos, expectativas y atención actual.' WHERE id = 35;
UPDATE tips SET title_es = 'El progreso alimenta la motivación', text_es = 'El progreso visible es uno de los mayores estímulos para la motivación. Incluso los pequeños avances pueden aumentar la perseverancia y la confianza.' WHERE id = 36;
UPDATE tips SET title_es = 'La repetición construye identidad', text_es = 'Las acciones que repites influyen en cómo te ves a ti mismo.\n\nCon el tiempo, los hábitos se convierten en pruebas que refuerzan tu imagen personal.' WHERE id = 37;
UPDATE tips SET title_es = 'Dormir protege la concentración', text_es = 'La atención, la memoria y la toma de decisiones dependen de un sueño de calidad.\n\nIncluso una falta leve de sueño puede reducir considerablemente el rendimiento cognitivo.' WHERE id = 38;
UPDATE tips SET title_es = 'El cerebro anticipa las recompensas', text_es = 'Anticipar una recompensa activa los sistemas de motivación del cerebro.\n\nA menudo, esperar una recompensa tiene más fuerza que recibirla.' WHERE id = 39;
UPDATE tips SET title_es = 'A los hábitos les gusta la constancia', text_es = 'Repetir una acción a la misma hora o en el mismo lugar fortalece la formación de hábitos.\n\nLas rutinas previsibles reducen la necesidad de esfuerzo consciente.' WHERE id = 40;
UPDATE tips SET title_es = 'La atención se capta con facilidad', text_es = 'Los sonidos repentinos, el movimiento, la novedad y el contraste atraen la atención de forma natural.\n\nEsta tendencia ayudó a nuestros antepasados a sobrevivir, pero hoy puede generar distracciones.' WHERE id = 41;
UPDATE tips SET title_es = 'El éxito genera más éxito', text_es = 'Los pequeños triunfos aumentan la confianza y hacen que los retos futuros parezcan más manejables.\n\nEl impulso suele crecer a partir de experiencias repetidas de logro.' WHERE id = 42;
UPDATE tips SET title_es = 'Tu cerebro detesta la ambigüedad', text_es = 'Los objetivos poco claros generan incertidumbre y dudas. Definir exactamente qué significa tener éxito facilita actuar con constancia.' WHERE id = 43;
UPDATE tips SET title_es = 'La dopamina impulsa la búsqueda', text_es = 'La dopamina está estrechamente relacionada con el deseo y la motivación. Fomenta la exploración y la búsqueda de objetivos, no solo el placer.' WHERE id = 44;
UPDATE tips SET title_es = 'Los hábitos pueden sobrevivir a la motivación', text_es = 'La motivación aparece y desaparece, pero los hábitos pueden mantenerse con poco esfuerzo consciente. Por eso los sistemas suelen superar a la fuerza de voluntad.' WHERE id = 45;
UPDATE tips SET title_es = 'La fuerza de voluntad no es infinita', text_es = 'El autocontrol puede resultar más difícil tras largos periodos de esfuerzo o estrés.\n\nGestionar la energía suele ser más eficaz que depender únicamente de la disciplina.' WHERE id = 46;
UPDATE tips SET title_es = 'Las señales visuales influyen en las decisiones', text_es = 'Lo que está a la vista suele elegirse con más frecuencia. Pequeños cambios en lo que ves cada día pueden influir mucho en tu conducta.' WHERE id = 47;
UPDATE tips SET title_es = 'Las recompensas refuerzan el aprendizaje', text_es = 'Es más probable que una conducta se repita cuando va seguida de un resultado satisfactorio.\n\nLa recompensa es uno de los mecanismos de aprendizaje más potentes del cerebro.' WHERE id = 48;
UPDATE tips SET title_es = 'El estrés estrecha la atención', text_es = 'El estrés dirige la atención hacia amenazas y preocupaciones inmediatas. Aunque esto puede ser útil para sobrevivir, también dificulta el pensamiento creativo.' WHERE id = 49;
UPDATE tips SET title_es = 'El cerebro busca la eficiencia', text_es = 'Las conductas repetidas se vuelven gradualmente automáticas porque la automatización ahorra energía.\n\nLos hábitos son la forma que tiene el cerebro de reducir la carga cognitiva.' WHERE id = 50;
UPDATE tips SET title_es = 'La curiosidad mejora la memoria', text_es = 'Cuando algo te despierta verdadera curiosidad, el cerebro está más receptivo al aprendizaje.\n\nLa información aprendida con curiosidad suele recordarse durante más tiempo.' WHERE id = 51;
UPDATE tips SET title_es = 'La fricción moldea la conducta', text_es = 'Los pequeños obstáculos pueden reducir mucho la probabilidad de realizar una acción.\n\nDel mismo modo, facilitar una conducta puede aumentar considerablemente las posibilidades de llevarla a cabo.' WHERE id = 52;
UPDATE tips SET title_es = 'El efecto de la mera exposición', text_es = 'Cuanto más te encuentras con algo, más familiar y atractivo suele parecerte.\n\nLa repetición influye en las preferencias más de lo que solemos imaginar.' WHERE id = 53;
UPDATE tips SET title_es = 'La energía influye en la disciplina', text_es = 'Muchos fallos de autocontrol son, en realidad, problemas de gestión de la energía.\n\nEl sueño, la alimentación y la recuperación suelen importar más que la motivación.' WHERE id = 54;
UPDATE tips SET title_es = 'Las recompensas pierden fuerza con el tiempo', text_es = 'El cerebro se adapta rápidamente a las recompensas repetidas. Lo que antes resultaba emocionante puede volverse normal y llevarnos a buscar novedades o retos mayores.' WHERE id = 55;
UPDATE tips SET title_es = 'Concentrarse exige descartar opciones', text_es = 'Concentrarse profundamente implica ignorar de forma activa innumerables alternativas.\n\nCada acto de atención también supone una omisión deliberada.' WHERE id = 56;
UPDATE tips SET title_es = 'El impulso existe', text_es = 'Completar una tarea productiva aumenta la probabilidad de empezar otra.\n\nEl refuerzo positivo puede hacer que el progreso genere más progreso.' WHERE id = 57;
UPDATE tips SET title_es = 'Los hábitos prosperan con la estabilidad', text_es = 'Los entornos estables facilitan mantener las rutinas. Los cambios frecuentes obligan al cerebro a tomar más decisiones y consumir más energía.' WHERE id = 58;
UPDATE tips SET title_es = 'La novedad activa la atención', text_es = 'Las experiencias nuevas atraen de forma natural los recursos cognitivos. El cerebro está preparado para detectar lo desconocido porque puede esconder oportunidades o amenazas.' WHERE id = 59;
UPDATE tips SET title_es = 'Las pausas breves reducen los impulsos', text_es = 'Incluso una pausa breve antes de actuar puede mejorar la toma de decisiones.\n\nUnos segundos de reflexión suelen bastar para reducir la conducta impulsiva.' WHERE id = 60;
UPDATE tips SET title_es = 'Cada hábito cuenta como un voto', text_es = 'Cada acción es un pequeño voto a favor de la persona en la que quieres convertirte.\n\nLa identidad se forma poco a poco mediante conductas repetidas, no con decisiones aisladas.' WHERE id = 61;
UPDATE tips SET title_es = 'El entorno puede hacer magia con la disciplina', text_es = 'La tentación más fácil de resistir es la que nunca aparece.\n\nDiseñar el entorno suele ser más eficaz que depender únicamente del autocontrol.' WHERE id = 62;
UPDATE tips SET title_es = 'La atención es tu recurso más valioso', text_es = 'El tiempo es limitado, pero la atención es aún más valiosa. La calidad de vida depende en gran medida de dónde diriges tu atención cada día.' WHERE id = 63;
UPDATE tips SET title_es = 'La motivación va y viene; los sistemas permanecen', text_es = 'La motivación puede ser imprevisible, pero los sistemas siguen funcionando cuando el entusiasmo desaparece.\n\nLos procesos constantes producen resultados fiables.' WHERE id = 64;
UPDATE tips SET title_es = 'Una mente distraída da vueltas en círculo', text_es = 'El esfuerzo sin concentración puede generar actividad sin progreso.\n\nLa concentración ayuda a convertir la energía en resultados significativos.' WHERE id = 65;
UPDATE tips SET title_es = 'Cada señal abre una puerta', text_es = 'Los pequeños estímulos pueden desencadenar cadenas de conducta poderosas. Muchos hábitos empiezan con una señal sencilla que indica al cerebro que es hora de actuar.' WHERE id = 66;
UPDATE tips SET title_es = 'El crecimiento está más allá de la comodidad', text_es = 'Rara vez se mejora permaneciendo en un territorio conocido.\n\nLos retos moderados fomentan la adaptación, el aprendizaje y el desarrollo de habilidades.' WHERE id = 67;
UPDATE tips SET title_es = 'La constancia vence a la intensidad', text_es = 'Los resultados extraordinarios suelen surgir de acciones normales repetidas durante mucho tiempo.\n\nLos hábitos sostenibles suelen superar a los esfuerzos intensos pero esporádicos.' WHERE id = 68;
UPDATE tips SET title_es = 'Tu yo futuro te observa', text_es = 'Las decisiones que tomas hoy moldean las oportunidades de mañana.\n\nLas pequeñas elecciones se acumulan y tienen consecuencias a largo plazo.' WHERE id = 69;
UPDATE tips SET title_es = 'La concentración es un superpoder', text_es = 'En una época de distracciones constantes, la capacidad de mantener la atención se ha vuelto cada vez más escasa y valiosa.' WHERE id = 70;
UPDATE tips SET title_es = 'La regla de los dos minutos', text_es = 'Los grandes hábitos suelen empezar con acciones muy pequeñas.\n\nSi iniciar una conducta lleva menos de dos minutos, es mucho más probable que la mantengas con regularidad.' WHERE id = 71;
UPDATE tips SET title_es = 'Actuar aporta claridad', text_es = 'A menudo esperamos a tener certeza antes de actuar, pero la acción genera información.\n\nEl progreso suele revelar cuál es el siguiente paso.' WHERE id = 72;
UPDATE tips SET title_es = 'A la memoria le gusta recuperar información', text_es = 'Recordar información activamente fortalece la memoria más que limitarse a repasarla.\n\nLa recuperación de recuerdos es como hacer ejercicio para el cerebro.' WHERE id = 73;
UPDATE tips SET title_es = 'El efecto de ponerse a prueba', text_es = 'Evaluarte es una de las estrategias de aprendizaje más eficaces. El esfuerzo de recuperar la información ayuda a crear recuerdos más sólidos.' WHERE id = 74;
UPDATE tips SET title_es = 'Elegir puede ser agotador', text_es = 'Tener más opciones no siempre produce mejores resultados. Un exceso de opciones puede aumentar el estrés, retrasar las decisiones y reducir la satisfacción.' WHERE id = 75;
UPDATE tips SET title_es = 'Los hábitos necesitan repetición, no perfección', text_es = 'La constancia a largo plazo importa más que hacerlo todo perfectamente.\n\nSaltarse un día rara vez importa; abandonar el hábito por completo sí.' WHERE id = 76;
UPDATE tips SET title_es = 'Las emociones dirigen la atención', text_es = 'Las experiencias emocionales captan la atención de forma natural y permanecen en la memoria.\n\nEl cerebro da prioridad a la información que considera personalmente significativa.' WHERE id = 77;
UPDATE tips SET title_es = 'El cerebro busca patrones', text_es = 'Los seres humanos detectamos patrones de forma natural. Encontrar estructuras nos ayuda a comprender el mundo y a hacer predicciones.' WHERE id = 78;
UPDATE tips SET title_es = 'Los plazos cambian la conducta', text_es = 'Las limitaciones crean urgencia y ayudan a establecer prioridades. Sin plazos, muchas tareas se alargan indefinidamente y pierden impulso.' WHERE id = 79;
UPDATE tips SET title_es = 'El primer paso lo cambia todo', text_es = 'Empezar una tarea suele reducir la ansiedad y la incertidumbre.\n\nUna vez que empiezas, el cerebro tiende a percibir el reto como más manejable.' WHERE id = 80;
UPDATE tips SET title_es = 'El contexto activa la memoria', text_es = 'Los recuerdos suelen estar vinculados al entorno en el que se formaron.\n\nVolver a un lugar conocido puede ayudarte a recordar información que parecía olvidada.' WHERE id = 81;
UPDATE tips SET title_es = 'Tu cerebro recompensa el progreso', text_es = 'El cerebro es muy sensible a las señales de avance.\n\nIncluso las pequeñas mejoras pueden generar emociones positivas que refuercen el esfuerzo.' WHERE id = 82;
UPDATE tips SET title_es = 'La atención funciona como un foco', text_es = 'Concentrarse intensamente en algo puede volver casi invisible el resto de la información.\n\nLo que percibes suele depender de aquello que ya estás buscando.' WHERE id = 83;
UPDATE tips SET title_es = 'La práctica fortalece las vías neuronales', text_es = 'Cada repetición fortalece los circuitos neuronales implicados en una habilidad.\n\nLa práctica constante hace gradualmente que las acciones sean más rápidas, fáciles y automáticas.' WHERE id = 84;
UPDATE tips SET title_es = 'Los entornos nuevos despiertan la creatividad', text_es = 'Los lugares nuevos exponen al cerebro a estímulos y perspectivas desconocidos. Esto puede fomentar el pensamiento flexible y generar ideas originales.' WHERE id = 85;
UPDATE tips SET title_es = 'Sobreestimamos la motivación futura', text_es = 'Muchas personas creen que en el futuro tendrán más disciplina y energía.\n\nPlanificar teniendo en cuenta la realidad de hoy suele ser más eficaz que confiar en la motivación de mañana.' WHERE id = 86;
UPDATE tips SET title_es = 'El éxito deja pistas', text_es = 'Estudiar lo que ya funciona puede ser tan valioso como identificar los errores.\n\nLos patrones de éxito suelen revelar estrategias prácticas que merece la pena repetir.' WHERE id = 87;
UPDATE tips SET title_es = 'La frustración forma parte del aprendizaje', text_es = 'Tener dificultades con un concepto puede resultar incómodo, pero ese esfuerzo suele fortalecer la comprensión y la retención con el tiempo.' WHERE id = 88;
UPDATE tips SET title_es = 'El contraste atrae la atención', text_es = 'Las diferencias de color, tamaño, movimiento o sonido atraen la atención de forma natural.\n\nNuestro cerebro evolucionó para detectar rápidamente lo que destaca.' WHERE id = 89;
UPDATE tips SET title_es = 'La constancia genera confianza', text_es = 'Las acciones repetidas generan confianza en tus capacidades. Cumplirte pequeñas promesas fortalece la seguridad en ti mismo y la fiabilidad.' WHERE id = 90;
UPDATE tips SET title_es = 'El cerebro prefiere las recompensas inmediatas', text_es = 'Las recompensas inmediatas suelen parecer más atractivas que los beneficios futuros, aunque sean mayores. Esta tendencia ayuda a explicar la procrastinación y las decisiones impulsivas.' WHERE id = 91;
UPDATE tips SET title_es = 'El progreso visible motiva', text_es = 'Registrar rachas, hitos o tareas completadas demuestra que estás avanzando.\n\nVer el progreso hace que los objetivos a largo plazo parezcan más alcanzables.' WHERE id = 92;
UPDATE tips SET title_es = 'La curiosidad es un imán cognitivo', text_es = 'Las preguntas sin respuesta atraen de forma natural la atención hacia sus soluciones.\n\nLa curiosidad convierte el aprendizaje en una actividad interesante, en lugar de una obligación.' WHERE id = 93;
UPDATE tips SET title_es = 'Aprender mejora cuando se distribuye en el tiempo', text_es = 'La información se retiene mejor cuando el aprendizaje se reparte en varias sesiones.\n\nLa repetición espaciada supera sistemáticamente al estudio intensivo de última hora.' WHERE id = 94;
UPDATE tips SET title_es = 'Los rituales reducen la carga mental', text_es = 'Las rutinas sencillas reducen la incertidumbre y conservan energía mental.\n\nLos rituales pueden ayudar a rendir de forma constante bajo presión.' WHERE id = 95;
UPDATE tips SET title_es = 'Tu estado de ánimo moldea la atención', text_es = 'Los estados emocionales influyen en qué información recibe prioridad.\n\nSegún cómo se sientan, las personas pueden percibir oportunidades y amenazas diferentes.' WHERE id = 96;
UPDATE tips SET title_es = 'Es más fácil mantener el progreso que iniciarlo', text_es = 'Crear impulso requiere esfuerzo, pero mantenerlo suele ser más sencillo.\n\nCuando un hábito ya está establecido, continuar se siente más natural.' WHERE id = 97;
UPDATE tips SET title_es = 'Las pequeñas mejoras se acumulan', text_es = 'Las pequeñas ganancias, repetidas con constancia, pueden producir grandes resultados a largo plazo.\n\nLa mejora suele llegar poco a poco antes de hacerse evidente.' WHERE id = 98;
UPDATE tips SET title_es = 'El cerebro aprende durante el descanso', text_es = 'El aprendizaje no se detiene cuando termina la práctica. Durante el descanso, el cerebro sigue procesando y organizando información.' WHERE id = 99;
UPDATE tips SET title_es = 'Dormir fortalece la memoria', text_es = 'El sueño desempeña un papel fundamental en la consolidación de los recuerdos.\n\nMientras descansas, la información importante se refuerza y se organiza.' WHERE id = 100;
UPDATE tips SET title_es = 'Los objetivos dirigen la atención', text_es = 'Los objetivos claros ayudan al cerebro a determinar qué importa y qué puede ignorar.\n\nSin una dirección, la atención es más vulnerable a las distracciones.' WHERE id = 101;
UPDATE tips SET title_es = 'Las recompensas moldean los hábitos', text_es = 'Es más probable que se repitan las conductas seguidas de resultados positivos.\n\nLa recompensa refuerza la conexión entre una acción y la conducta futura.' WHERE id = 102;
UPDATE tips SET title_es = 'La identidad influye en la conducta', text_es = 'Las personas tienden a actuar de acuerdo con la imagen que tienen de sí mismas.\n\nCambiar cómo te ves puede influir en lo que haces habitualmente.' WHERE id = 103;
UPDATE tips SET title_es = 'Los descansos mejoran el rendimiento', text_es = 'La concentración sostenida se beneficia de pausas ocasionales para recuperarse.\n\nLos descansos bien planificados ayudan a conservar la atención y reducir el cansancio mental.' WHERE id = 104;
UPDATE tips SET title_es = 'El esfuerzo aumenta el valor', text_es = 'A menudo valoramos más los resultados cuando hemos invertido esfuerzo para alcanzarlos.\n\nLas recompensas que cuestan conseguir suelen parecer más significativas.' WHERE id = 105;
UPDATE tips SET title_es = 'Las normas sociales son poderosas', text_es = 'La conducta humana está muy influida por las acciones de los demás.\n\nA menudo adaptamos nuestras decisiones a lo que parece normal dentro de un grupo.' WHERE id = 106;
UPDATE tips SET title_es = 'La atención puede convertirse en un hábito', text_es = 'Aquello en lo que te concentras repetidamente influye en lo que percibirás en el futuro.\n\nCon el tiempo, los patrones de atención pueden volverse automáticos.' WHERE id = 107;
UPDATE tips SET title_es = 'La incertidumbre alimenta la curiosidad', text_es = 'Las lagunas de conocimiento despiertan un deseo natural de aprender.\n\nAl cerebro a menudo le cuesta ignorar las preguntas sin respuesta.' WHERE id = 108;
UPDATE tips SET title_es = 'La reflexión favorece el crecimiento', text_es = 'Dedicar tiempo a revisar las experiencias ayuda a convertirlas en aprendizajes.\n\nLa reflexión transforma la actividad en aprendizaje, y el aprendizaje en sabiduría.' WHERE id = 109;
UPDATE tips SET title_es = 'Dominar una habilidad requiere práctica deliberada', text_es = 'Los expertos mejoran trabajando en debilidades concretas, en vez de repetir lo que ya saben hacer.\n\nLa práctica enfocada acelera el desarrollo de habilidades.' WHERE id = 110;
